<%- include('partials/header') %>

<h1>Painel administrativo</h1>
<p>Gerencie usuários, serviços e contratos da plataforma.</p>

<section class="panel">
  <h2>Usuários</h2>
  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Nome</th>
          <th>E-mail</th>
          <th>Tipo</th>
          <th>Status</th>
          <th>Ação</th>
        </tr>
      </thead>
      <tbody>
        <% users.forEach(item => { %>
          <tr>
            <td><%= item.name %></td>
            <td><%= item.email %></td>
            <td><%= item.role %></td>
            <td><%= item.suspended ? 'Suspenso' : 'Ativo' %></td>
            <td>
              <% if (item.role !== 'admin') { %>
                <% if (item.suspended) { %>
                  <form action="/admin/users/<%= item.id %>/activate" method="POST">
                    <button class="small-button" type="submit">Reativar</button>
                  </form>
                <% } else { %>
                  <form action="/admin/users/<%= item.id %>/suspend" method="POST">
                    <button class="small-button danger" type="submit">Suspender</button>
                  </form>
                <% } %>
              <% } else { %>
                -
              <% } %>
            </td>
          </tr>
        <% }) %>
      </tbody>
    </table>
  </div>
</section>

<section class="panel">
  <h2>Serviços</h2>
  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Título</th>
          <th>Dono</th>
          <th>Preço</th>
          <th>Status</th>
          <th>Ações</th>
        </tr>
      </thead>
      <tbody>
        <% services.forEach(service => { %>
          <tr>
            <td><%= service.title %></td>
            <td><%= service.owner_name %> (<%= service.owner_email %>)</td>
            <td>R$ <%= Number(service.price).toFixed(2).replace('.', ',') %></td>
            <td><span class="badge <%= service.status %>"><%= service.status %></span></td>
            <td class="actions">
              <% if (service.status !== 'approved') { %>
                <form action="/admin/services/<%= service.id %>/approve" method="POST">
                  <button class="small-button" type="submit">Aprovar</button>
                </form>
              <% } %>
              <% if (service.status !== 'removed') { %>
                <form action="/admin/services/<%= service.id %>/remove" method="POST">
                  <button class="small-button danger" type="submit">Remover</button>
                </form>
              <% } %>
            </td>
          </tr>
        <% }) %>
      </tbody>
    </table>
  </div>
</section>

<section class="panel">
  <h2>Contratos</h2>
  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Serviço</th>
          <th>Prestador</th>
          <th>Cliente</th>
          <th>Status</th>
          <th>Criado em</th>
        </tr>
      </thead>
      <tbody>
        <% contracts.forEach(contract => { %>
          <tr>
            <td><%= contract.service_title %></td>
            <td><%= contract.provider_name %></td>
            <td><%= contract.client_name %></td>
            <td><span class="badge <%= contract.status %>"><%= contract.status %></span></td>
            <td><%= contract.created_at %></td>
          </tr>
        <% }) %>
      </tbody>
    </table>
  </div>
</section>

<%- include('partials/footer') %>

=== public/style.css ===
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f4f6f8;
  color: #1f2937;
}

a {
  color: #2563eb;
  text-decoration: none;
}

.topbar {
  background: #111827;
  color: white;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.brand {
  color: white;
  font-size: 22px;
  font-weight: 800;
}

.nav {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.nav a {
  color: white;
}

.inline {
  display: inline;
}

.link-button {
  border: 0;
  background: transparent;
  color: white;
  cursor: pointer;
  font: inherit;
  padding: 0;
}

.container {
  width: min(1120px, calc(100% - 32px));
  margin: 24px auto;
}

.hero {
  background: linear-gradient(135deg, #2563eb, #7c3aed);
  color: white;
  padding: 42px;
  border-radius: 18px;
  margin-bottom: 28px;
}

.hero h1 {
  margin-top: 0;
  font-size: clamp(30px, 5vw, 52px);
}

.hero p {
  font-size: 18px;
  max-width: 700px;
}

.button,
.small-button {
  display: inline-block;
  border: 0;
  background: #2563eb;
  color: white;
  padding: 12px 18px;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 700;
  text-align: center;
  margin-top: 8px;
}

.button.secondary {
  background: white;
  color: #2563eb;
  margin-left: 8px;
}

.button.full {
  width: 100%;
}

.small-button {
  padding: 8px 11px;
  border-radius: 8px;
  margin-top: 0;
  font-size: 14px;
}

.small-button.danger {
  background: #dc2626;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 18px;
}

.card,
.panel,
.form-card,
.service-detail {
  background: white;
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.08);
}

.card h3 {
  margin-top: 0;
}

.muted {
  color: #6b7280;
}

.empty {
  background: white;
  padding: 18px;
  border-radius: 12px;
  color: #6b7280;
}

.alert {
  background: #e0f2fe;
  border: 1px solid #7dd3fc;
  color: #075985;
  padding: 12px;
  border-radius: 10px;
  margin-bottom: 16px;
}

.alert.error {
  background: #fee2e2;
  border-color: #fca5a5;
  color: #991b1b;
}

.alert.success {
  background: #dcfce7;
  border-color: #86efac;
  color: #166534;
}

.form-page {
  display: flex;
  justify-content: center;
}

.form-card {
  width: min(440px, 100%);
}

.form-card.wide {
  width: min(720px, 100%);
}

label {
  display: block;
  margin-top: 14px;
  margin-bottom: 6px;
  font-weight: 700;
}

input,
textarea,
select {
  width: 100%;
  padding: 12px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  font: inherit;
}

textarea {
  resize: vertical;
}

.page-title {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  flex-wrap: wrap;
}

.panel {
  margin-top: 22px;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
}

th,
td {
  text-align: left;
  padding: 12px;
  border-bottom: 1px solid #e5e7eb;
  vertical-align: middle;
}

th {
  background: #f8fafc;
}

.badge {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  background: #e5e7eb;
}

.badge.pending {
  background: #fef3c7;
  color: #92400e;
}

.badge.approved,
.badge.active {
  background: #dcfce7;
  color: #166534;
}

.badge.removed,
.badge.cancelled {
  background: #fee2e2;
  color: #991b1b;
}

.badge.completed {
  background: #dbeafe;
  color: #1e40af;
}

.actions,
.row-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.row-actions select {
  min-width: 130px;
}

.service-detail {
  max-width: 820px;
  margin: 0 auto;
}

.service-detail h1 {
  margin-top: 0;
}

.price {
  font-size: 30px;
  font-weight: 800;
  margin: 18px 0;
  color: #16a34a;
}

.description {
  white-space: pre-wrap;
  line-height: 1.7;
}

.footer {
  text-align: center;
  color: #6b7280;
  padding: 32px 16px;
}

@media (max-width: 640px) {
  .topbar {
    align-items: flex-start;
  }

  .nav {
    width: 100%;
  }

  .hero {
    padding: 28px;
  }

  .button.secondary {
    margin-left: 0;
  }

  .button {
    width: 100%;
  }

  .actions,
  .row-actions {
    flex-direction: column;
    align-items: stretch;
  }
}
